import { NextResponse } from 'next/server';
import { ZodError } from 'zod';
import { ApiError as GenAIError } from '@google/genai';
import type { ApiError, ApiErrorCode } from '@/contracts/api';
import {
  ConflictError,
  NotFoundError,
  RateLimitedError,
  UnauthorizedError,
  UnprocessableError,
} from './errors';

const STATUS_BY_CODE: Record<ApiErrorCode, number> = {
  UNAUTHORIZED: 401,
  BAD_REQUEST: 400,
  NOT_FOUND: 404,
  CONFLICT: 409,
  RATE_LIMITED: 429,
  UPSTREAM_UNAVAILABLE: 502,
  UNPROCESSABLE: 422,
  PAYLOAD_TOO_LARGE: 413,
  INTERNAL: 500,
};

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** Path ids go straight into SQL; a malformed one should be a 404, not a Postgres 500. */
export const isUuid = (id: string) => uuid.test(id);

const QUOTA_MESSAGE = 'The AI service is out of quota right now. Try again in a minute.';
/** Gemini returns HTTP 429 when the project's quota is used up. */
const isGeminiQuota = (err: unknown) => err instanceof GenAIError && err.status === 429;

export function jsonOk<T>(data: T, init?: ResponseInit) {
  return NextResponse.json(data, init);
}

export function jsonError(code: ApiErrorCode, message: string, details?: unknown): NextResponse<ApiError> {
  return NextResponse.json({ error: { code, message, details } }, { status: STATUS_BY_CODE[code] });
}

export function jsonErrorFromZod(error: ZodError): NextResponse<ApiError> {
  return jsonError('BAD_REQUEST', 'Validation failed', error.flatten());
}

