4	export const PROVIDER_TIMEOUT_MS = 4000;
5	/** Both providers serve the Open Food Facts dataset (§10.1), so the attribution is the same. */
6	export const ATTRIBUTION = 'Open Food Facts, ODbL';
7	
8	export interface ProviderProduct {
9	  name: string;
10	  brand: string | null;
11	  imageUrl: string | null;
12	  categories: string[];
13	  allergenTags: Product['allergenTags'];
14	  packageQuantity: PackageQuantity | null;
