16	  per100: Nutrients;
17	  /** Per-serving values as printed by the provider, when it has any. */
18	  perServing: Nutrients | null;
19	}
20	
21	export type ProviderResult =
22	  | { result: 'hit'; data: ProviderProduct; raw: unknown; httpStatus: number; ms: number }
23	  | { result: 'miss'; httpStatus?: number; ms: number }
24	  | { result: 'error'; httpStatus?: number; ms: number };
25	
26	/** The parsed outcome of one HTTP response, before timing is attached. */
27	export type ParsedResponse = { result: 'hit'; data: ProviderProduct } | { result: 'miss' } | { result: 'error' };
28	
29	/** GET with the provider timeout. A network failure, timeout or unreadable 2xx body is an `error`. */
30	export async function fetchProvider(
31	  url: string,
32	  headers: Record<string, string>,
33	  parse: (status: number, body: unknown) => ParsedResponse,
34	): Promise<ProviderResult> {
35	  const started = performance.now();
36	  const ms = () => Math.round(performance.now() - started);
37	  let httpStatus: number | undefined;
38	  try {
39	    const res = await fetch(url, { headers, signal: AbortSignal.timeout(PROVIDER_TIMEOUT_MS), cache: 'no-store' });
40	    httpStatus = res.status;
41	    const text = await res.text();
42	    let body: unknown = null;
43	    let unreadable = false;
44	    try {
45	      body = text ? JSON.parse(text) : null;
46	    } catch {
47	      unreadable = true;
48	    }
49	    // A 2xx we can't read says nothing about whether the product exists, so it can't be a miss.
50	    if (unreadable && res.ok) return { result: 'error', httpStatus, ms: ms() };
51	    const parsed = parse(res.status, body);
52	    if (parsed.result === 'hit') return { result: 'hit', data: parsed.data, raw: body, httpStatus, ms: ms() };
53	    return { result: parsed.result, httpStatus, ms: ms() };
54	  } catch {
55	    return { result: 'error', httpStatus, ms: ms() };
56	  }
57	}
