96	/**
97	 * Read-only pantry view for recipe matching (F6 step 1): quantity > 0,
98	 * expired excluded, sorted by daysToExpiry, capped at 25.
99	 */
100	export async function listPantryForMatching(
101	  userId: string,
102	  tz: string,
103	  now = new Date(),
104	  limit = 25,
105	): Promise<PantryItem[]> {
106	  const rows = await sql<PantryRow[]>`
107	    SELECT * FROM pantry_items
108	    WHERE user_id = ${userId} AND quantity_base > 0
109	    ORDER BY expiry_date NULLS LAST, normalized_name
110	  `;
111	  return pantryForMatching(rows, tz, now, limit);
112	}
113	
114	/** Matching view of pantry rows: in stock, not expired, soonest expiry first (FEFO). Shared with finish. */
115	export function pantryForMatching(rows: PantryRow[], tz: string, now = new Date(), limit = 25): PantryItem[] {
116	  return rows
117	    .filter((row) => Number(row.quantity_base) > 0)
118	    .map((row) => rowToPantryItem(row, tz, now))
119	    .filter((item) => item.daysToExpiry == null || item.daysToExpiry >= 0)
120	    .sort((a, b) => (a.daysToExpiry ?? 9999) - (b.daysToExpiry ?? 9999))
121	    .slice(0, limit);
122	}
