124	export async function getPantryItem(userId: string, id: string, tz: string): Promise<PantryItem | null> {
125	  const rows = await sql<PantryRow[]>`
126	    SELECT * FROM pantry_items WHERE user_id = ${userId} AND id = ${id} LIMIT 1
127	  `;
128	  const row = rows[0];
129	  return row ? rowToPantryItem(row, tz) : null;
130	}
