132	export async function listPantryByIds(userId: string, ids: string[], tz: string): Promise<PantryItem[]> {
133	  if (ids.length === 0) return [];
134	  const rows = await sql<PantryRow[]>`SELECT * FROM pantry_items WHERE user_id = ${userId} AND id = ANY(${ids})`;
135	  return rows.map((row) => rowToPantryItem(row, tz));
136	}
