138	export async function getProfileFilters(userId: string): Promise<{ diets: string[]; allergens: string[]; tz: string }> {
139	  const rows = await sql<{ diets: string[]; allergens: string[]; tz: string }[]>`
140	    SELECT diets, allergens, tz FROM users WHERE id = ${userId} LIMIT 1
141	  `;
