24	const bodySchema = z.object({
25	  mustUsePantryItemIds: z.array(z.string().uuid()).optional(),
26	  freeText: z.string().max(100).optional(),
27	  maxResults: z.number().int().min(1).max(10).default(6),
28	  extraDiets: z.array(z.enum(['vegetarian', 'vegan', 'gluten_free', 'dairy_free', 'high_protein'])).optional(),
29	});
