31	const CONCURRENCY = 5;
32	const MAX_URLS = 12;
33	
34	export async function POST(req: Request) {
35	  try {
36	    const user = await requireUser();
37	    const parsed = bodySchema.safeParse(await req.json().catch(() => ({})));
38	    if (!parsed.success) return jsonErrorFromZod(parsed.error); // bad bodies don't spend rate-limit tokens
39	    const body = parsed.data;
40	    const limit = checkRateLimit(user.id, 'recipes/search');
41	    if (!limit.ok) throw new RateLimitedError('Too many recipe searches', limit.retryAfterMs);
42	
43	    return ndjsonResponse<RecipeSearchEvent>(async (write, signal) => {
44	      write({ type: 'status', stage: 'searching', message: 'Finding recipes for your expiring ingredients…' });
45	
46	      const profile = await getProfileFilters(user.id);
47	      const diets = [...new Set([...profile.diets, ...(body.extraDiets ?? [])])] as DietFlag[];
48	      const allergens = profile.allergens as Allergen[];
49	      const pantry = await listPantryForMatching(user.id, profile.tz, new Date(), 200);
50	
51	      const mustUseIds =
52	        body.mustUsePantryItemIds ?? pantry.filter((p) => p.daysToExpiry != null && p.daysToExpiry <= 3).map((p) => p.id);
53	      const ctx = buildDiscoveryContext(pantry, { diets, allergens }, body.freeText);
54	      if (body.mustUsePantryItemIds) {
55	        ctx.expiring = pantry.filter((p) => mustUseIds.includes(p.id));
56	        ctx.alsoAvailable = pantry.filter((p) => !mustUseIds.includes(p.id));
57	      }
58	
59	      const cacheKey = discoveryCacheKey({
60	        expiring: ctx.expiring.map((p) => p.normalizedName),
61	        diets,
62	        allergens,
63	        freeText: body.freeText,
64	      });
65	      let urls = await getDiscoveryCache(user.id, cacheKey);
66	      const cached = urls != null;
67	      if (!urls) {
68	        const discovered = await discoverRecipeUrls(ctx);
69	        urls = collectDiscoveryUrls(discovered.result).slice(0, MAX_URLS);
70	        await setDiscoveryCache(user.id, cacheKey, urls).catch(() => {});
71	        if (discovered.result.searchEntryPointHtml) {
72	          write({ type: 'search_suggestions', html: discovered.result.searchEntryPointHtml });
73	        }
74	      }
75	
76	      if (urls.length === 0) {
77	        write({ type: 'done', total: 0, excludedCount: 0, cached });
78	        return;
79	      }
80	
81	      write({ type: 'status', stage: 'fetching', message: `Checking ${urls.length} recipes…` });
82	
83	      const seenCanonical = new Set<string>();
84	      let shown = 0;
85	      let reserved = 0; // result slots claimed synchronously, so parallel workers can't overshoot maxResults
86	      let excludedCount = 0;
87	      let next = 0;
88	      const stop = () => reserved >= body.maxResults || signal.aborted;
89	
90	      const worker = async () => {
91	        while (next < urls.length && !stop()) {
92	          const url = urls[next++]!;
93	          try {
94	            const fetched = await safeFetchHtml(url, { signal });
95	            const extracted = await extractRecipe(fetched.text, fetched.finalUrl);
96	            if (!extracted) {
97	              excludedCount++;
98	              write({ type: 'excluded', url, reason: 'no_recipe_markup' });
99	              continue;
100	            }
101	            if (seenCanonical.has(extracted.canonicalUrl)) {
102	              excludedCount++;
103	              write({ type: 'excluded', url, reason: 'duplicate' });
104	              continue;
105	            }
106	            seenCanonical.add(extracted.canonicalUrl);
107	            const outcome = await processExtracted(extracted, { pantry, diets, allergens });
108	            if (outcome.kind === 'excluded') {
109	              excludedCount++;
110	              write({ type: 'excluded', url, reason: outcome.reason, detail: outcome.detail });
111	              continue;
112	            }
113	            if (stop()) return;
114	            reserved++; // claim the slot before awaiting
115	            let emitted = false;
116	            try {
117	              const persisted = await persistOriginal(user.id, extracted, outcome.ingredients);
118	              const [score] = computeScores(
119	                [
120	                  {
121	                    ingredients: outcome.ingredients,
122	                    matches: outcome.matches,
123	                    proteinPerServingG: outcome.nutrition.perServing.proteinG,
124	                  },
125	                ],
126	                { highProtein: diets.includes('high_protein') },
127	              );
128	              const candidate: RecipeCandidate = {
129	                recipeId: persisted.recipeId,
130	                title: extracted.title,
131	                source: {
132	                  url: extracted.canonicalUrl,
133	                  siteName: extracted.siteName,
134	                  author: extracted.author,
135	                  retrievedAt: new Date().toISOString(),
136	                  extractionMethod: extracted.extractionMethod,
137	                },
138	                totalMin: extracted.times.totalMin,
139	                servings: extracted.servings,
140	                score: score!,
141	                usesExpiring: outcome.usesExpiring,
142	                matches: outcome.matches,
143	                nutrition: outcome.nutrition,
144	              };
145	              shown++;
146	              emitted = true;
147	              write({ type: 'candidate', candidate });
148	            } finally {
149	              if (!emitted) reserved--; // persist failed: free the slot for another URL
150	            }
151	          } catch (err) {
152	            excludedCount++;
153	            if (err instanceof SafeFetchError && err.code === 'blocked_url') {
154	              write({ type: 'excluded', url, reason: 'blocked_url', detail: err.message });
155	            } else {
156	              write({
157	                type: 'excluded',
158	                url,
159	                reason: 'fetch_failed',
160	                detail: err instanceof Error ? err.message.slice(0, 200) : 'fetch failed',
161	              });
162	            }
163	          }
164	        }
165	      };
166	
167	      await Promise.all(Array.from({ length: Math.min(CONCURRENCY, urls.length) }, () => worker()));
168	      write({ type: 'done', total: shown, excludedCount, cached });
169	    });
170	  } catch (err) {
171	    return handleRouteError(err);
172	  }
173	}
