18	
19	    const { id } = await ctx.params;
20	    if (!isUuid(id)) return jsonError('NOT_FOUND', 'Recipe not found');
21	    const detail = await getRecipeDetail(user.id, id);
22	    if (!detail) return jsonError('NOT_FOUND', 'Recipe not found');
23	
24	    const profile = await getProfileFilters(user.id);
