26	    const allergens = profile.allergens as Allergen[];
27	    const pantry = await listPantryForMatching(user.id, profile.tz, new Date(), 200);
28	    const pantryById = new Map(pantry.map((p) => [p.id, p]));
29	
30	    const matches = matchIngredients(detail.original.ingredients, pantry);
31	    const missing = matches.filter((m) => m.status === 'missing' || m.status === 'insufficient');
32	    if (missing.length === 0) throw new ConflictError('Nothing to adapt — you have every ingredient.');
33	
34	    const missingRaws = missing.map((m) => detail.original.ingredients[m.ingredientIndex]!.raw);
35	
36	    // Cached variant covering the same missing set (F9 step 5).
37	    const cached = findMatchingAdaptation(detail.adaptations, missingRaws);
38	    if (cached && adaptationStillAllowed(cached, { diets, allergens })) {
39	      const parsed = cached.ingredients.map((i) => i.parsed);
40	      const nutrition = estimateRecipeNutrition({
41	        ingredients: parsed,
42	        matches: matchIngredients(parsed, pantry),
43	        pantryById,
44	        servings: detail.original.servings,
45	      });
46	      const body: AdaptResponse = { adaptation: cached, nutrition };
47	      return jsonOk(body);
48	    }
49	
50	    // Only a real Gemini call spends a token (not 404s, 409s or cached adaptations).
51	    const limit = checkRateLimit(user.id, 'recipes/adapt');
52	    if (!limit.ok) throw new RateLimitedError('Too many adaptations', limit.retryAfterMs);
53	    const built = await requestAdaptation(detail.original, missingRaws, pantry, { diets, allergens });
54	    const parsed = built.ingredients.map((i) => i.parsed);
55	    const nutrition = estimateRecipeNutrition({
56	      ingredients: parsed,
57	      matches: matchIngredients(parsed, pantry),
58	      pantryById,
59	      servings: detail.original.servings,
60	    });
61	    const adaptation = await insertAdaptation(user.id, id, detail.original.variantId, { ...built, nutrition });
62	
63	    const body: AdaptResponse = { adaptation, nutrition };
64	    return jsonOk(body);
65	  } catch (err) {
