119	function usedInSteps(name: string | null, steps: RecipeStep[]): number[] {
120	  if (!name) return [];
121	  const tokens = name.toLowerCase().split(/[\s-]+/).filter((t) => t.length > 3);
122	  if (tokens.length === 0) return [];
123	  const out: number[] = [];
124	  steps.forEach((s, i) => {
125	    const lower = s.text.toLowerCase();
126	    if (tokens.some((t) => lower.includes(t))) out.push(i);
127	  });
128	  return out;
