136	  const ratio = Number(session.servings_planned) / variantServings;
137	  const steps = (variant.steps as RecipeStep[]) ?? [];
138	  const ingredients = variantIngredients(variant).map((ing) => {
139	    const scaled = ing.parsed.qtyBase != null && ing.parsed.dim != null ? ing.parsed.qtyBase * ratio : null;
