142	      changed: ing.changed,
143	      scaledQtyDisplay:
144	        scaled != null && ing.parsed.dim ? formatQty(scaled, ing.parsed.dim, ing.parsed.unit ?? undefined) : null,
145	      usedInSteps: usedInSteps(ing.parsed.normalizedName ?? ing.parsed.name, steps),
146	    };
