168	export async function updateSession(
169	  userId: string,
170	  sessionId: string,
171	  input: { currentStep?: number; status?: 'abandoned' },
172	): Promise<CookingSession> {
173	  const bundle = await loadSessionBundle(userId, sessionId);
174	  if (!bundle) throw new NotFoundError('Cooking session not found');
175	  if (bundle.session.status !== 'in_progress') throw new ConflictError('Session is no longer in progress');
176	  const steps = (bundle.variant.steps as RecipeStep[]) ?? [];
177	  if (input.currentStep != null && (input.currentStep < 0 || input.currentStep >= steps.length)) {
178	    throw new ConflictError(`Step out of range (0–${steps.length - 1})`);
179	  }
180	  const rows = await sql<SessionRow[]>`
181	    UPDATE cooking_sessions
182	    SET current_step = COALESCE(${input.currentStep ?? null}, current_step),
183	        status = COALESCE(${input.status ?? null}, status)
184	    WHERE id = ${sessionId} AND user_id = ${userId} AND status = 'in_progress'
185	    RETURNING id, recipe_variant_id, status, current_step, servings_planned, servings_cooked, servings_eaten, started_at, finished_at
186	  `;
187	  const updated = rows[0];
188	  if (!updated) throw new ConflictError('Session is no longer in progress');
189	  return toCookingSession(bundle.recipe.id, bundle.variant.kind, updated);
190	}
