2	import sql from '@/lib/db';
3	import { ConflictError, NotFoundError } from '@/lib/errors';
4	import { estimateRecipeNutrition, suggestLogPerServing } from '@/server/nutrition/recipe';
5	import { matchIngredients } from '@/server/recipes/match';
6	import { pantryForMatching, type PantryRow } from '@/server/recipes/pantry-view';
7	import type { FinishRequest, FinishResult } from '@/contracts/api';
8	import type { CookingSession, MealLog, Nutrients, RecipeIngredient, RecipeStep, Substitution } from '@/contracts/domain';
9	
10	interface SessionRow {
11	  id: string;
12	  recipe_variant_id: string;
13	  status: CookingSession['status'];
14	  current_step: number;
15	  servings_planned: string | number;
16	  servings_cooked: string | number | null;
17	  servings_eaten: string | number | null;
18	  started_at: Date;
19	  finished_at: Date | null;
20	}
21	
22	function localDateInTz(tz: string, now = new Date()): string {
23	  return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
24	}
25	
26	/**
27	 * Finish-cooking transaction (F14): one DB transaction that (1) marks the
28	 * session finished with an idempotency guard, (2) deducts confirmed pantry
29	 * lines with clamping, and (3) inserts a meal-log snapshot.
30	 */
31	export async function finishSession(userId: string, sessionId: string, input: FinishRequest): Promise<FinishResult> {
32	  for (const d of input.deductions) {
33	    if (!Number.isFinite(d.qtyBase) || d.qtyBase < 0) {
34	      throw new ConflictError('Deduction quantities must be non-negative numbers');
35	    }
36	  }
37	
38	  return sql.begin(async (tx) => {
39	    // Ownership pre-check: another user's session (or a missing one) is a 404,
40	    // so only genuine replays of our own session reach the 409 guard below.
41	    const owned = await tx<Array<{ id: string }>>`
42	      SELECT id FROM cooking_sessions WHERE id = ${sessionId} AND user_id = ${userId} LIMIT 1
43	    `;
44	    if (!owned[0]) throw new NotFoundError('Cooking session not found');
45	
46	    const updated = await tx<SessionRow[]>`
47	      UPDATE cooking_sessions
48	      SET status = 'finished', finished_at = now(),
49	          servings_cooked = ${input.servingsCooked}, servings_eaten = ${input.servingsEaten}
50	      WHERE id = ${sessionId} AND user_id = ${userId} AND status = 'in_progress'
51	      RETURNING id, recipe_variant_id, status, current_step, servings_planned, servings_cooked, servings_eaten, started_at, finished_at
52	    `;
53	    const session = updated[0];
54	    if (!session) throw new ConflictError('Session is not in progress (already finished or abandoned)');
55	
56	    const variants = await tx<
57	      Array<{ id: string; recipe_id: string; kind: 'original' | 'ai_adapted'; servings: string | number; ingredients: unknown; steps: unknown; substitutions: unknown }>
58	    >`SELECT id, recipe_id, kind, servings, ingredients, steps, substitutions FROM recipe_variants WHERE id = ${session.recipe_variant_id} LIMIT 1`;
59	    const variant = variants[0];
60	    if (!variant) throw new NotFoundError('Recipe variant not found');
61	    const recipes = await tx<
62	      Array<{ id: string; title: string; publisher_nutrition: Nutrients | null }>
63	    >`SELECT id, title, publisher_nutrition FROM recipes WHERE id = ${variant.recipe_id} AND user_id = ${userId} LIMIT 1`;
64	    const recipe = recipes[0];
65	    if (!recipe) throw new NotFoundError('Recipe not found');
66	
67	    const parsed: RecipeIngredient[] =
68	      variant.kind === 'original'
69	        ? ((variant.ingredients as RecipeIngredient[]) ?? [])
70	        : (((variant.ingredients as Array<{ parsed: RecipeIngredient }>) ?? []).map((i) => i.parsed));
71	
72	    // Same view as the finish preview (FEFO, no expired items), read inside the transaction.
73	    const users = await tx<Array<{ tz: string }>>`SELECT tz FROM users WHERE id = ${userId} LIMIT 1`;
74	    const tz = users[0]?.tz ?? 'America/Vancouver';
75	    const pantryRows = await tx<PantryRow[]>`
76	      SELECT * FROM pantry_items WHERE user_id = ${userId}
77	      ORDER BY expiry_date NULLS LAST, normalized_name
78	    `; // same order as the preview, so ties resolve to the same rows
79	    const pantry = pantryForMatching(pantryRows, tz, new Date(), 200);
80	    const pantryById = new Map(pantry.map((p) => [p.id, p]));
81	
82	    const matches = matchIngredients(parsed, pantry);
83	    const estimate = estimateRecipeNutrition({
84	      ingredients: parsed,
85	      matches,
86	      pantryById,
87	      servings: Number(variants[0]!.servings),
88	    });
89	    const suggested = suggestLogPerServing(estimate, recipe.publisher_nutrition);
90	    const perServing = input.perServingOverride ?? { kcal: suggested.kcal, proteinG: suggested.proteinG };
91	
92	    const pantryUpdates: FinishResult['pantryUpdates'] = [];
93	    for (const d of input.deductions) {
94	      const locked = await tx<Array<{ id: string; name: string; quantity_base: string | number }>>`
95	        SELECT id, name, quantity_base FROM pantry_items
96	        WHERE id = ${d.pantryItemId} AND user_id = ${userId} LIMIT 1 FOR UPDATE
97	      `;
98	      const row = locked[0];
99	      if (!row) throw new NotFoundError('Pantry item not found');
100	      const before = Number(row.quantity_base);
101	      const take = Math.min(before, d.qtyBase);
102	      const after = before - take;
103	      await tx`UPDATE pantry_items SET quantity_base = ${after}, updated_at = now() WHERE id = ${row.id}`;
104	      await tx`
105	        INSERT INTO pantry_events (user_id, pantry_item_id, kind, delta_base, cooking_session_id)
106	        VALUES (${userId}, ${row.id}, 'cook_deduct', ${-take}, ${sessionId})
107	      `;
108	      pantryUpdates.push({ pantryItemId: row.id, name: row.name, beforeBase: before, afterBase: after });
109	    }
110	
111	    let mealLog: MealLog | null = null;
112	    if (input.servingsEaten > 0) {
113	      const eatenAt = new Date();
114	      const inserted = await tx<Array<{ id: string; eaten_at: Date }>>`
115	        INSERT INTO meal_logs (user_id, local_date, source, cooking_session_id, recipe_variant_id, label, servings, kcal, protein_g, carbs_g, fat_g)
116	        VALUES (
117	          ${userId}, ${localDateInTz(tz, eatenAt)}, 'cooking_session',
118	          ${sessionId}, ${session.recipe_variant_id}, ${recipe.title}, ${input.servingsEaten},
119	          ${perServing.kcal * input.servingsEaten}, ${perServing.proteinG * input.servingsEaten}, NULL, NULL
120	        )
121	        RETURNING id, eaten_at
122	      `;
123	      const logRow = inserted[0]!;
124	      mealLog = {
125	        id: logRow.id,
126	        eatenAt: logRow.eaten_at.toISOString(),
127	        localDate: localDateInTz(tz, eatenAt),
128	        source: 'cooking_session',
129	        label: recipe.title,
130	        servings: input.servingsEaten,
131	        kcal: perServing.kcal * input.servingsEaten,
132	        proteinG: perServing.proteinG * input.servingsEaten,
133	        carbsG: null,
134	        fatG: null,
135	        cookingSessionId: sessionId,
136	        pantryItemId: null,
137	      };
138	    }
139	
140	    return {
141	      session: {
142	        id: session.id,
143	        recipeId: recipe.id,
144	        variantId: session.recipe_variant_id,
145	        variantKind: variants[0]!.kind,
146	        status: session.status,
147	        currentStep: session.current_step,
148	        servingsPlanned: Number(session.servings_planned),
149	        startedAt: session.started_at.toISOString(),
150	        finishedAt: session.finished_at ? session.finished_at.toISOString() : null,
151	      },
152	      pantryUpdates,
153	      mealLog,
154	    };
155	  });
156	}
